arguments.query:
query Feed5Context {
  feeds(first: 100, offset: 0, orderBy: "published_at", orderDir: "desc") {
    nodes { id title status publishedAt feedBadge game { id name slug } }
    pageInfo { total first offset hasMore nextOffset }
  }
  gears: search(query: "Gears of War: E-Day", first: 8) { games { id name slug status coverUrl backgroundUrl } }
  battlefield: search(query: "Battlefield 6", first: 8) { games { id name slug status coverUrl backgroundUrl } }
  gta: search(query: "GTA Online", first: 8) { games { id name slug status coverUrl backgroundUrl } }
  ghost: search(query: "Ghost of Yōtei", first: 8) { games { id name slug status coverUrl backgroundUrl } }
  wolverine: search(query: "Marvel's Wolverine", first: 8) { games { id name slug status coverUrl backgroundUrl } }
}
